using System.Collections.Generic; using Crownfall.Core; using UnityEngine;
namespace Crownfall.Units { public sealed class ShieldSystem { sealed class S{public float v,t; public S(float v,float t){this.v=v;this.t=t;}} readonly List<S> shields=new(); public float Total{get{float x=0;foreach(var s in shields)x+=s.v;return x;}} public void Add(float value,float duration){if(value>0)shields.Add(new S(value,Mathf.Max(0,duration)));} public float Absorb(float damage){for(int i=shields.Count-1;i>=0&&damage>0;i--){float a=Mathf.Min(shields[i].v,damage);shields[i].v-=a;damage-=a;if(shields[i].v<=0)shields.RemoveAt(i);}return damage;} public void Tick(BattleClock c){if(c==null)return;for(int i=shields.Count-1;i>=0;i--){shields[i].t-=c.DeltaTime;if(shields[i].t<=0)shields.RemoveAt(i);}} public void Clear()=>shields.Clear(); } }
